// Generated by AI (UnitTest MCP)
//! ADR-0119 decisions 1, 7, 9's two-phase Lifecycle purge workflow: preview,
//! then a separate confirmation against the exact previewed scope and
//! cutoff. Every route is tenant- and repository-scoped the same way
//! `handlers::repository::claims` already is; a request or receipt is only
//! ever disclosed to the principal that made it.

use std::time::{Duration, SystemTime, UNIX_EPOCH};

use ackplane_server::administration_store::{
    PurgeDataCategory, PurgeOutcome, PurgePreviewRequest, PurgeReceipt, MAX_CONFIRMATION_WINDOW,
};
use axum::{
    extract::{Path, State},
    http::StatusCode,
    Json,
};
use serde::{Deserialize, Serialize};

use super::{administration_error_status, AdministrationApiState};

/// Telemetry events have no separate recovery mechanism yet; naming that
/// plainly (ADR-0119 decision 7's "recovery implications") is more honest
/// than a generic disclaimer.
const RECOVERY_IMPLICATIONS: &str = "Purged telemetry events cannot be recovered by this Bridge; take a platform Snapshot first if retention requires preserving them.";

#[derive(Deserialize)]
pub(super) struct PreviewPurgeRequest {
    policy_id: String,
    /// Only `telemetry_events` today; see `PurgeDataCategory`.
    data_category: String,
    older_than_seconds: u64,
    confirmation_window_seconds: u64,
    idempotency_key: String,
}

#[derive(Serialize)]
pub(super) struct PurgePreviewResponse {
    request_id: String,
    data_category: &'static str,
    older_than_seconds: u64,
    preview_row_count: i64,
    confirmation_expires_at_seconds: Option<u64>,
    recovery_implications: &'static str,
    idempotent_replay: bool,
}

pub(super) async fn preview_lifecycle_purge(
    State(state): State<AdministrationApiState>,
    Path(repository_id): Path<String>,
    Json(request): Json<PreviewPurgeRequest>,
) -> Result<Json<PurgePreviewResponse>, StatusCode> {
    ensure_repository_visible(&state, &repository_id).await?;
    let data_category =
        parse_data_category(&request.data_category).ok_or(StatusCode::BAD_REQUEST)?;
    let older_than =
        unix_seconds_to_system_time(request.older_than_seconds).ok_or(StatusCode::BAD_REQUEST)?;
    let confirmation_window = Duration::from_secs(request.confirmation_window_seconds);
    if confirmation_window.is_zero() || confirmation_window > MAX_CONFIRMATION_WINDOW {
        return Err(StatusCode::BAD_REQUEST);
    }

    let now = SystemTime::now();
    let preview_request = PurgePreviewRequest {
        policy_id: request.policy_id,
        requested_by: state.tenant_id.to_string(),
        tenant_id: state.tenant_id.to_string(),
        repository_id,
        data_category,
        older_than,
        confirmation_window,
        idempotency_key: request.idempotency_key,
    };
    let mut administration = state.administration.lock().await;
    let outcome = administration
        .preview_purge(&preview_request, now)
        .await
        .map_err(administration_error_status)?;
    Ok(Json(PurgePreviewResponse {
        request_id: outcome.request.request_id,
        data_category: data_category_label(outcome.request.data_category),
        older_than_seconds: unix_seconds(outcome.request.older_than).unwrap_or(0),
        preview_row_count: outcome.request.preview_row_count,
        confirmation_expires_at_seconds: unix_seconds(outcome.request.confirmation_expires_at),
        recovery_implications: RECOVERY_IMPLICATIONS,
        idempotent_replay: outcome.idempotent_replay,
    }))
}

#[derive(Serialize)]
pub(super) struct PurgeReceiptResponse {
    receipt_id: String,
    outcome: &'static str,
    reason: String,
    rows_deleted: Option<i64>,
    occurred_at_seconds: Option<u64>,
}

impl From<PurgeReceipt> for PurgeReceiptResponse {
    fn from(receipt: PurgeReceipt) -> Self {
        Self {
            receipt_id: receipt.receipt_id,
            outcome: purge_outcome_label(receipt.outcome),
            reason: receipt.reason,
            rows_deleted: receipt.rows_deleted,
            occurred_at_seconds: unix_seconds(receipt.occurred_at),
        }
    }
}

pub(super) async fn confirm_lifecycle_purge(
    State(state): State<AdministrationApiState>,
    Path((repository_id, request_id)): Path<(String, String)>,
) -> Result<Json<PurgeReceiptResponse>, StatusCode> {
    ensure_repository_visible(&state, &repository_id).await?;
    let now = SystemTime::now();
    let mut administration = state.administration.lock().await;
    // The request itself names its `requested_by` principal and
    // `repository_id`; only the exact tenant and repository that made it may
    // confirm it, mirroring `platform_snapshot_receipt`'s same rule.
    let request = administration
        .purge_request(&request_id)
        .await
        .map_err(administration_error_status)?
        .ok_or(StatusCode::NOT_FOUND)?;
    if request.requested_by != state.tenant_id.as_ref() || request.repository_id != repository_id {
        return Err(StatusCode::NOT_FOUND);
    }
    let receipt = administration
        .confirm_purge(&request.request_id, now)
        .await
        .map_err(administration_error_status)?;
    Ok(Json(receipt.into()))
}

pub(super) async fn lifecycle_purge_status(
    State(state): State<AdministrationApiState>,
    Path((repository_id, request_id)): Path<(String, String)>,
) -> Result<Json<PurgeReceiptResponse>, StatusCode> {
    ensure_repository_visible(&state, &repository_id).await?;
    let mut administration = state.administration.lock().await;
    // Same ownership rule as `confirm_lifecycle_purge` above: a request or
    // receipt is only disclosed to the tenant/repository that made it.
    let request = administration
        .purge_request(&request_id)
        .await
        .map_err(administration_error_status)?
        .ok_or(StatusCode::NOT_FOUND)?;
    if request.requested_by != state.tenant_id.as_ref() || request.repository_id != repository_id {
        return Err(StatusCode::NOT_FOUND);
    }
    let receipt = administration
        .purge_receipt_for_request(&request_id)
        .await
        .map_err(administration_error_status)?
        .ok_or(StatusCode::NOT_FOUND)?;
    Ok(Json(receipt.into()))
}

async fn ensure_repository_visible(
    state: &AdministrationApiState,
    repository_id: &str,
) -> Result<(), StatusCode> {
    state
        .fleet
        .repository(state.tenant_id.as_ref(), repository_id)
        .await
        .map_err(|error| {
            tracing::error!(%error, "Bridge Administration purge repository lookup failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?;
    Ok(())
}

fn parse_data_category(value: &str) -> Option<PurgeDataCategory> {
    match value {
        "telemetry_events" => Some(PurgeDataCategory::TelemetryEvents),
        _ => None,
    }
}

fn data_category_label(category: PurgeDataCategory) -> &'static str {
    match category {
        PurgeDataCategory::TelemetryEvents => "telemetry_events",
    }
}

fn purge_outcome_label(outcome: PurgeOutcome) -> &'static str {
    match outcome {
        PurgeOutcome::Succeeded => "succeeded",
        PurgeOutcome::Failed => "failed",
        PurgeOutcome::Refused => "refused",
        PurgeOutcome::Expired => "expired",
    }
}

fn unix_seconds_to_system_time(seconds: u64) -> Option<SystemTime> {
    UNIX_EPOCH.checked_add(Duration::from_secs(seconds))
}

fn unix_seconds(timestamp: SystemTime) -> Option<u64> {
    timestamp
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|d| d.as_secs())
}

