    #[test]
    fn parse_data_category_accepts_only_the_closed_vocabulary() {
        assert_eq!(
            parse_data_category("telemetry_events"),
            Some(PurgeDataCategory::TelemetryEvents)
        );
        assert_eq!(parse_data_category("claims"), None);
        assert_eq!(parse_data_category(""), None);
    }

    #[test]
    fn unix_seconds_round_trips_through_system_time() {
        let time = unix_seconds_to_system_time(1_700_000_000).expect("a valid unix time");
        assert_eq!(unix_seconds(time), Some(1_700_000_000));
    }
